// Generates provenance and signatures for the release artifact using local
// key material. Creates an Ed25519 key pair under keys/ if absent (the
// private key never leaves the machine), writes an in-toto Statement v0.1
// with an SLSA provenance v0.2 predicate, and produces detached signatures
// over the tarball and the provenance. Deterministic: no timestamps and
// Ed25519 signing is deterministic, so identical inputs and key material
// yield identical provenance and signature bytes.
const fs = require("fs");
const crypto = require("crypto");

const pkg = require("./package.json");

const MATERIALS = [
  "package.json",
  "index.js",
  "build.js",
  "sbom.js",
  "release.sh",
  "README.md",
  "package-lock.json",
];

const TAR = `${pkg.name}-${pkg.version}.tgz`;
const sha256 = (f) => crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex");

fs.mkdirSync("keys", { recursive: true });
if (!fs.existsSync("keys/release-private.pem")) {
  const { privateKey, publicKey } = crypto.generateKeyPairSync("ed25519");
  fs.writeFileSync("keys/release-private.pem", privateKey.export({ type: "pkcs8", format: "pem" }), { mode: 0o600 });
  fs.writeFileSync("keys/release-public.pem", publicKey.export({ type: "spki", format: "pem" }));
  console.log("generated new ed25519 key pair in keys/");
}
const privateKey = crypto.createPrivateKey(fs.readFileSync("keys/release-private.pem"));
const publicKey = crypto.createPublicKey(fs.readFileSync("keys/release-public.pem"));

const statement = {
  _type: "https://in-toto.io/Statement/v0.1",
  subject: [{ name: TAR, digest: { sha256: sha256(TAR) } }],
  predicateType: "https://slsa.dev/provenance/v0.2",
  predicate: {
    builder: { id: `local:${pkg.name}/release.sh@${pkg.version}` },
    buildType: "custom:shell-release-v1",
    invocation: {
      configSource: { uri: "file:release.sh", digest: { sha256: sha256("release.sh") } },
      parameters: {},
      environment: {},
    },
    materials: MATERIALS.map((f) => ({ uri: `file:${f}`, digest: { sha256: sha256(f) } })),
  },
};
const provenance = JSON.stringify(statement, null, 2) + "\n";
fs.writeFileSync("provenance.intoto.json", provenance);

const sign = (data) => crypto.sign(null, data, privateKey).toString("base64") + "\n";
fs.writeFileSync(`${TAR}.sig`, sign(fs.readFileSync(TAR)));
fs.writeFileSync("provenance.intoto.json.sig", sign(Buffer.from(provenance, "utf8")));

const verify = (file, sigFile) =>
  crypto.verify(null, fs.readFileSync(file), publicKey, Buffer.from(fs.readFileSync(sigFile, "utf8").trim(), "base64"));
if (!verify(TAR, `${TAR}.sig`) || !verify("provenance.intoto.json", "provenance.intoto.json.sig")) {
  throw new Error("signature self-verification failed");
}
console.log(`provenance.intoto.json written; signed ${TAR} and provenance (verified OK)`);
